when HTTP_REQUEST {
    if { [HTTP::method] eq "OPTIONS" } {
        HTTP::respond 204 \
            "Access-Control-Allow-Origin" "*" \
            "Access-Control-Allow-Methods" "GET, POST, PUT, DELETE, OPTIONS" \
            "Access-Control-Allow-Headers" "Authorization, Content-Type" \
            "Access-Control-Max-Age" "86400"
        return
    }
}
when HTTP_RESPONSE {
    HTTP::header insert "Access-Control-Allow-Origin" "*"
    HTTP::header insert "Access-Control-Allow-Credentials" "true"
}

when HTTP_RESPONSE {
    set uri [HTTP::uri]
    if { [regexp -nocase {\.(jpg|jpeg|png|gif|css|js|ico|woff2?)$} $uri] } {
        HTTP::header replace "Cache-Control" "public, max-age=2592000, immutable"
    } elseif { [HTTP::header value "Content-Type"] contains "application/json" } {
        HTTP::header replace "Cache-Control" "no-store, no-cache, must-revalidate"
    } else {
        HTTP::header replace "Cache-Control" "no-cache, must-revalidate"
    }
}

