when HTTP_REQUEST {
    set rate_limit 100
    set time_window 60
    set block_dur 300
    set cip [IP::client_addr]
    set key "rl_${cip}"
    set blk "blk_${cip}"
    if { [table lookup $blk] ne "" } {
        HTTP::respond 429 content "Too Many Requests" "Content-Type" "text/plain" "Retry-After" "${block_dur}"
        return
    }
    set count [table incr -mustexist $key]
    if { $count eq "" } { table set $key 1 $time_window; set count 1 }
    if { $count > $rate_limit } {
        table set $blk 1 $block_dur
        log local0.warn "Rate limit: $cip (${count} req)"
        HTTP::respond 429 content "Too Many Requests" "Content-Type" "text/plain"
    }
}

when HTTP_REQUEST {
    set uri [string tolower [HTTP::uri]]
    foreach pattern { "union+select" "union%20select" "' or '" "1=1" "drop+table"
                      "insert+into" "xp_cmdshell" "information_schema" "sleep(" "waitfor+delay" } {
        if { [string match "*${pattern}*" $uri] } {
            log local0.warn "SQLi: [IP::client_addr] URI: $uri"
            HTTP::respond 403 content "Forbidden" "Content-Type" "text/plain"
            return
        }
    }
}

when HTTP_REQUEST {
    set ua [string tolower [HTTP::header value "User-Agent"]]
    if { $ua eq "" } { HTTP::respond 403 content "Forbidden" "Content-Type" "text/plain"; return }
    foreach bad { "nikto" "sqlmap" "nessus" "masscan" "zgrab" "dirbuster" "w3af" "acunetix" "netsparker" } {
        if { $ua contains $bad } {
            log local0.warn "Bad UA: $ua from [IP::client_addr]"
            HTTP::respond 403 content "Forbidden" "Content-Type" "text/plain"
            return
        }
    }
}

when HTTP_REQUEST {
    set allowed { GET POST PUT DELETE OPTIONS HEAD PATCH }
    set method [HTTP::method]
    if { $method eq "TRACE" || !([lsearch $allowed $method] >= 0) } {
        log local0.warn "Blocked method: $method from [IP::client_addr]"
        HTTP::respond 405 content "Method Not Allowed" "Content-Type" "text/plain" "Allow" "GET, POST, PUT, DELETE, OPTIONS, HEAD, PATCH"
    }
}

# HashDoS (CVE-2011-3414) koruması — PHP/Java/Ruby/Python etkilenir
# Saldırgan binlerce POST parameter göndererek hash collision ile CPU tüketir
# Kaynak: F5 DevCentral — HashDoS iRule
when HTTP_REQUEST {
    set max_params 1000
    if { [HTTP::method] ne "POST" } { return }
    set ctype [HTTP::header value "Content-Type"]
    if { [string match -nocase "*application/x-www-form-urlencoded*" $ctype] } {
        set clen [HTTP::header value "Content-Length"]
        if { $clen ne "" && $clen > 0 } { HTTP::collect $clen }
    }
}
when HTTP_REQUEST_DATA {
    set body [HTTP::payload]
    set count [expr {[llength [split $body "&"]]}]
    if { $count > $max_params } {
        log local0.warn "HashDoS attempt: [IP::client_addr] sent ${count} params (limit: ${max_params})"
        HTTP::respond 413 content "Payload Too Large" "Content-Type" "text/plain"
    }
}

# Slowloris saldırısı — bağlantıyı açık tutup yavaş veri gönderir
# Request tamamlanmadan timeout tetikleyerek kaynak tüketir
when CLIENT_ACCEPTED {
    set req_start [clock seconds]
    set max_req_time 10
}
when HTTP_REQUEST {
    set elapsed [expr {[clock seconds] - $req_start}]
    if { $elapsed > $max_req_time } {
        log local0.warn "Slowloris: [IP::client_addr] took ${elapsed}s to send request"
        TCP::close
        return
    }
    # Incomplete headers check
    set clen [HTTP::header value "Content-Length"]
    if { $clen ne "" && $clen > 1048576 } {
        log local0.warn "Large body: [IP::client_addr] Content-Length=${clen}"
    }
}
when HTTP_REQUEST_SEND {
    # Reset counter after successful request
    set req_start [clock seconds]
}

# Session cookie'lerini AES ile şifrele — client-side tampering önler
# F5 DevCentral klasik pattern — cookie encrypt/decrypt komutları
when HTTP_RESPONSE {
    # Backend'den gelen Set-Cookie'leri şifrele
    foreach cname { "JSESSIONID" "PHPSESSID" "ASP.NET_SessionId" "session_id" } {
        if { [HTTP::cookie exists $cname] } {
            HTTP::cookie secure $cname enable
            HTTP::cookie httponly $cname enable
            HTTP::cookie encrypt $cname "MyStr0ng-P@ssphrase-2024" 256
        }
    }
}
when HTTP_REQUEST {
    # Client'tan gelen cookie'leri çöz ve doğrula
    foreach cname { "JSESSIONID" "PHPSESSID" "ASP.NET_SessionId" "session_id" } {
        if { [HTTP::cookie exists $cname] } {
            if { [catch { HTTP::cookie decrypt $cname "MyStr0ng-P@ssphrase-2024" 256 }] } {
                log local0.warn "Cookie tampering: [IP::client_addr] bad ${cname}"
                HTTP::cookie remove $cname
                HTTP::respond 400 content "Bad Cookie"
                return
            }
        }
    }
}

# HTTP Request Smuggling (CL.TE / TE.CL) engelleme
# Content-Length + Transfer-Encoding çakışması — CVE-2019-16869, vb.
when HTTP_REQUEST {
    set has_cl [HTTP::header exists "Content-Length"]
    set has_te [HTTP::header exists "Transfer-Encoding"]
    # Her ikisi de varsa — smuggling riski
    if { $has_cl && $has_te } {
        log local0.warn "HTTP Smuggling attempt: [IP::client_addr] both CL+TE headers"
        HTTP::respond 400 content "Bad Request" "Content-Type" "text/plain"
        return
    }
    # Multiple Content-Length
    if { [llength [HTTP::header values "Content-Length"]] > 1 } {
        log local0.warn "Multiple CL: [IP::client_addr]"
        HTTP::respond 400 content "Bad Request"
        return
    }
    # Invalid Transfer-Encoding obfuscation
    set te [string tolower [HTTP::header value "Transfer-Encoding"]]
    if { $te ne "" && $te ne "chunked" && $te ne "identity" } {
        log local0.warn "Obfuscated TE: [IP::client_addr] TE=${te}"
        HTTP::respond 400 content "Bad Request"
        return
    }
}

