# TLS handshake fingerprint — bot/malware tespit
# CLIENTSSL_HANDSHAKE event'inde TLS parametreleri analiz edilir
when CLIENTSSL_CLIENTHELLO {
    set tls_ver [SSL::cipher version]
    set ciphers [SSL::extensions -type 0x000d]
    # Bilinen kötü JA3 hash'leri (threat intel'den güncellenir)
    set bad_ja3s {
        "b32309a26951912be7dba376398abc3b"
        "e7d705a3286e19ea42f587b344ee6865"
    }
    # Datagroup'tan kontrol edilebilir:
    # class match $ja3_hash equals bad_ja3_dg
    log local0.info "TLS: cli=[IP::client_addr] ver=${tls_ver}"
}
when CLIENTSSL_HANDSHAKE {
    set cipher [SSL::cipher name]
    # Weak cipher tespit
    if { [string match -nocase "*RC4*" $cipher] || [string match -nocase "*EXPORT*" $cipher] || [string match -nocase "*NULL*" $cipher] } {
        log local0.warn "Weak cipher: [IP::client_addr] ${cipher}"
        reject
    }
}

# WebSocket hijacking / origin bypass koruması
when HTTP_REQUEST {
    set upgrade [string tolower [HTTP::header value "Upgrade"]]
    if { $upgrade eq "websocket" } {
        set origin [HTTP::header value "Origin"]
        set allowed_origins {
            "https://www.example.com"
            "https://app.example.com"
        }
        if { [lsearch -exact $allowed_origins $origin] < 0 } {
            log local0.warn "WS bad origin: [IP::client_addr] origin=${origin}"
            HTTP::respond 403 content "Forbidden"
            return
        }
        # WS version zorunlu
        set ws_ver [HTTP::header value "Sec-WebSocket-Version"]
        if { $ws_ver ne "13" } {
            HTTP::respond 426 content "Upgrade Required" "Sec-WebSocket-Version" "13"
            return
        }
        # WS key zorunlu
        if { [HTTP::header value "Sec-WebSocket-Key"] eq "" } {
            HTTP::respond 400 content "Bad WS Request"
            return
        }
    }
}

# Büyük payload DoS + buffer overflow koruma
when HTTP_REQUEST {
    set max_body 10485760   ;# 10 MB
    set max_uri 8192        ;# 8 KB
    set max_headers 16384   ;# 16 KB
    # URI uzunluğu
    if { [string length [HTTP::uri]] > $max_uri } {
        log local0.warn "Long URI: [IP::client_addr] len=[string length [HTTP::uri]]"
        HTTP::respond 414 content "URI Too Long"
        return
    }
    # Header toplam
    set total_hdr 0
    foreach hname [HTTP::header names] {
        incr total_hdr [string length "${hname}: [HTTP::header value $hname]"]
    }
    if { $total_hdr > $max_headers } {
        log local0.warn "Large headers: [IP::client_addr] size=${total_hdr}"
        HTTP::respond 431 content "Request Header Fields Too Large"
        return
    }
    # Body
    set clen [HTTP::header value "Content-Length"]
    if { $clen ne "" && $clen > $max_body } {
        log local0.warn "Large body: [IP::client_addr] CL=${clen}"
        HTTP::respond 413 content "Payload Too Large"
        return
    }
}

# Log4j JNDI injection — Header + URI + Body tara
when HTTP_REQUEST {
    # Pattern: ${jndi:...} — basit + obfuscated
    set jndi_re {\$\{\s*(?:[a-zA-Z]+:)?\s*j\s*n\s*d\s*i\s*:}
    # URI
    if { [regexp -nocase $jndi_re [HTTP::uri]] } {
        log local0.warn "Log4Shell URI: [IP::client_addr] uri=[HTTP::uri]"
        HTTP::respond 403 content "Forbidden"
        return
    }
    # Headers (User-Agent, X-Api-Version, Referer, vb.)
    foreach hname [HTTP::header names] {
        set hval [HTTP::header value $hname]
        if { [regexp -nocase $jndi_re $hval] } {
            log local0.warn "Log4Shell hdr: [IP::client_addr] ${hname}=${hval}"
            HTTP::respond 403 content "Forbidden"
            return
        }
    }
    # POST body collect
    if { [HTTP::method] eq "POST" } {
        set clen [HTTP::header value "Content-Length"]
        if { $clen ne "" && $clen > 0 && $clen < 1048576 } { HTTP::collect $clen }
    }
}
when HTTP_REQUEST_DATA {
    if { [regexp -nocase {\$\{\s*(?:[a-zA-Z]+:)?\s*j\s*n\s*d\s*i\s*:} [HTTP::payload]] } {
        log local0.warn "Log4Shell body: [IP::client_addr]"
        HTTP::respond 403 content "Forbidden"
        return
    }
}

# Tor exit node listesinden gelen trafiği engelle
# Datagroup: tor_exit_nodes (günlük cron ile güncellenir)
# Kaynak: https://check.torproject.org/exit-addresses
when CLIENT_ACCEPTED {
    set cip [IP::client_addr]
    if { [class match $cip equals tor_exit_nodes] } {
        log local0.warn "Tor block: ${cip}"
        reject
        return
    }
}
when HTTP_REQUEST {
    # Whitelist header ile bypass (test amaçlı)
    if { [HTTP::header value "X-Bypass-Tor"] eq "secret-token-2024" } { return }
    if { [class match [IP::client_addr] equals tor_exit_nodes] } {
        HTTP::respond 403 content "Anonymous proxy detected" "Content-Type" "text/plain"
    }
}
