when HTTP_REQUEST {
    set uri [HTTP::uri]
    if { [string match "/api/*" $uri] } { pool api_pool; return }
    if { [string match "/static/*" $uri] || [string match "/assets/*" $uri] } { pool static_pool; return }
    if { [string match "/admin/*" $uri] } {
        if { [IP::addr [IP::client_addr] mask 10.0.0.0/8] } { pool admin_pool } else { HTTP::respond 403 content "Forbidden" }
        return
    }
    pool default_pool
}

when HTTP_REQUEST {
    set host [string tolower [getfield [HTTP::host] ":" 1]]
    switch $host {
        "api.example.com"    { pool api_pool }
        "www.example.com"    { pool web_pool }
        "admin.example.com"  { pool admin_pool }
        default { log local0.warn "Unknown host: $host"; HTTP::respond 404 content "Not Found" }
    }
}

when HTTP_REQUEST {
    if { [HTTP::header value "X-Canary"] eq "true" } { pool canary_pool; return }
    if { [expr {int(rand() * 100)}] < 10 } {
        pool canary_pool
        HTTP::header insert "X-Routed-To" "canary"
    } else {
        pool production_pool
        HTTP::header insert "X-Routed-To" "production"
    }
}

when HTTP_REQUEST {
    set ver [HTTP::header value "X-API-Version"]
    set tenant [HTTP::header value "X-Tenant-ID"]
    switch $ver { "v2" { pool api_v2_pool } "v3" { pool api_v3_pool } default { pool api_v1_pool } }
    if { $tenant ne "" } { persist uie $tenant }
}

when HTTP_REQUEST {
    set req_time [clock milliseconds]
    set cip [IP::client_addr]; set meth [HTTP::method]; set hst [HTTP::host]; set uri [HTTP::uri]
}
when HTTP_RESPONSE {
    set dur [expr {[clock milliseconds] - $req_time}]
    log local0.info "ACCESS cip=${cip} method=${meth} host=${hst} uri=${uri} status=[HTTP::status] ms=${dur}"
}

when HTTP_REQUEST {
    set t0 [clock milliseconds]; set ruri [HTTP::uri]; set rmth [HTTP::method]; set cip [IP::client_addr]
}
when HTTP_RESPONSE {
    set st [HTTP::status]
    if { $st >= 500 } {
        set dur [expr {[clock milliseconds] - $t0}]
        log local0.err "SERVER_ERROR status=${st} cip=${cip} method=${rmth} uri=${ruri} server=[LB::server addr] ms=${dur}"
        if { $st == 503 } { log local0.err "POOL_DOWN active=[active_members [LB::server pool]]" }
    }
}

when HTTP_REQUEST { set t0 [clock milliseconds]; set ruri [HTTP::uri]; set cip [IP::client_addr] }
when HTTP_RESPONSE {
    set dur [expr {[clock milliseconds] - $t0}]
    if { $dur > 3000 } {
        log local0.warn "SLOW_RESP uri=${ruri} cip=${cip} ms=${dur} server=[LB::server addr] status=[HTTP::status]"
    }
}
